ALTER TABLE "commerce"."flows" DROP CONSTRAINT "flows_trigger";--> statement-breakpoint
ALTER TABLE "commerce"."flows" ADD COLUMN "trigger_event" text;--> statement-breakpoint
ALTER TABLE "commerce"."flows" ADD CONSTRAINT "flows_trigger_event" CHECK (("commerce"."flows"."trigger" = 'custom.event') = ("commerce"."flows"."trigger_event" is not null) and ("commerce"."flows"."trigger_event" is null or "commerce"."flows"."trigger_event" ~ '^[a-z][a-z0-9_]{0,39}$'));--> statement-breakpoint
ALTER TABLE "commerce"."flows" ADD CONSTRAINT "flows_trigger" CHECK ("commerce"."flows"."trigger" in ('subscriber.subscribed', 'order.paid', 'checkout.abandoned', 'order.sent', 'subscription.started', 'subscription.cancelled', 'form.response', 'quote.requested', 'review.created', 'order.refunded', 'return.requested', 'conversation.ended', 'conversation.rated', 'deal.created', 'deal.won', 'contract.signed', 'customer.lapsed', 'customer.browsed', 'subscriber.asleep', 'customer.birthday', 'segment.entered', 'schedule', 'tag.added', 'custom.event'));